const ts=t=>{const d=new Date(t*1000);return d.toLocaleDateString('en-GB',{day:'2-digit',month:'2-digit'})+' '+d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})};
const pill=(v,on)=>v==null?'<i class="pill na">—</i>':'<i class="pill '+(v>=1?'win':'loss')+'"'+(on?'':' style="opacity:.4" title="outside the current filter of this project"')+'>'+v.toFixed(2)+'x</i>';
let D=null,SK='entry_ts',SD=-1;
function best(r){const v=[r.proj==='core'?r.x_t15s40:null,r.proj==='core'?r.x_flow4:null,r.proj==='core'?r.x_split:null,r.proj==='P4'?r.x_t15s40:null,r.proj==='P5'?(r.strategy==='p5e50'?r.x_t15s40:r.x_h2t40):null].filter(x=>x!=null);return v.length?Math.max(...v):null}
function render(){const R=D.rows.map(r=>({...r,p45:r.proj==='P4'?r.x_t15s40:r.proj==='P5'?(r.strategy==='p5e50'?r.x_t15s40:r.x_h2t40):null,miss:(()=>{const b=best(r);return b&&r.after?r.after/b:null})()}));
R.sort((a,b)=>{const x=a[SK],y=b[SK];return (x==null)-(y==null)||(x>y?1:x<y?-1:0)*SD});
const n=R.length,ran2=R.filter(r=>r.after>=2).length,ran4=R.filter(r=>r.after>=4).length,lv=R.filter(r=>r.exit_reason==='lowvol').length,lvRan=R.filter(r=>r.exit_reason==='lowvol'&&r.after_peak_mult!=null&&r.after_peak_mult>=1.5*(best(r)||1)).length;
$('#kpis').innerHTML='<div class="kpi"><b>'+n+'</b><span>sold coins in '+D.days+' day(s)</span></div><div class="kpi"><b>'+ran2+'</b><span>went to 2x+ of our entry within 24 h</span></div><div class="kpi"><b>'+ran4+'</b><span>went to 4x+ within 24 h</span></div><div class="kpi"><b>'+lv+'</b><span>closed by the golden rule (volume < $25K)</span></div><div class="kpi"><b>'+lvRan+'</b><span>of those later ran 1.5× above our best exit</span></div>';
$('#t tbody').innerHTML=R.length?R.map(r=>'<tr><td><a class="coin" href="https://dexscreener.com/solana/'+r.mint+'" target="_blank" rel="noopener">'+r.name+'</a>'+(r.proj!=='core'?'<span class="tag '+r.proj.toLowerCase()+'">'+r.proj+'</span>':'')+'</td><td>'+ts(r.entry_ts)+'</td><td>$'+fmt(r.entry_mc)+'</td><td style="color:'+(r.exit_reason==='lowvol'?'#ffd75f':'#8f8fc8')+'">'+(r.exit_reason||'—')+'</td><td>'+(r.proj==='core'?pill(r.x_t15s40,r.p1in):'<i class="pill na">—</i>')+'</td><td>'+(r.proj==='core'?pill(r.x_flow4,r.p2in):'<i class="pill na">—</i>')+'</td><td>'+(r.proj==='core'?pill(r.x_split,true):'<i class="pill na">—</i>')+'</td><td>'+(r.proj==='core'?'<i class="pill na">—</i>':pill(r.p45,true))+'</td><td>'+(r.peak_mult?r.peak_mult.toFixed(2)+'x':'—')+'</td><td class="'+(r.after>=2?'big':'')+'">'+(r.after?r.after.toFixed(2)+'x':'—')+(r.px_suspect===1?'<span title="bad price reading suspected — real large buys only reached '+(r.px_verified_mult||0).toFixed(2)+'x" style="color:#ffd75f"> ⚠ '+(r.px_verified_mult||0).toFixed(2)+'x real?</span>':'')+'</td><td>$'+fmt(r.after_peak_mc)+'</td><td class="'+(r.after_last_mult==null?'':r.after_last_mult>=1?'up':'dn')+'">'+(r.after_last_mult!=null?r.after_last_mult.toFixed(2)+'x':'—')+'</td><td class="'+(r.miss>=1.5?'big':'mut')+'">'+(r.miss?r.miss.toFixed(2)+'× our best exit':'—')+'</td></tr>').join(''):'<tr><td colspan="13" class="mut">no sold coins in this period</td></tr>';
$('#sub').textContent=n+' sold coins · updated '+new Date().toLocaleTimeString()}
